(() => {
  const heading = [...document.querySelectorAll('div')].find(el => el.textContent === 'Cost');
  if (heading?.previousElementSibling?.textContent !== 'Status' || heading.nextElementSibling?.textContent !== 'Updated') return false;
  const left = heading.getBoundingClientRect().left;
  return ['$0.014', '$0.022'].every((amount, i) => {
    const cell = document.querySelector('[title="Total review cost · ' + amount + '"]');
    if (!cell || !cell.parentElement.textContent.includes('#' + (481 + i))) return false;
    const style = getComputedStyle(cell);
    return cell.innerText.includes(amount) && cell.getBoundingClientRect().left === left &&
      style.color === getComputedStyle(heading).color && style.fontFamily.includes('monospace') &&
      !cell.closest('a, button, [tabindex]');
  });
})()
